#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

class Array {
private:
    int* data;
    int size;

public:
    Array() : data(nullptr), size(0) {}

    Array(int n) : size(n) {
        if (n <= 0) {
            data = nullptr;
            size = 0;
        } else {
            data = new int[n];
        }
    }

    Array(const Array& other) : size(other.size) {
        if (size <= 0) {
            data = nullptr;
        } else {
            data = new int[size];
            for (int i = 0; i < size; i++) {
                data[i] = other.data[i];
            }
        }
    }

    ~Array() {
        delete[] data;
    }

    void read() {
        for (int i = 0; i < size; i++) {
            cin >> data[i];
        }
    }

    void setElement(int index, int value) {
        if (index >= 0 && index < size) {
            data[index] = value;
        }
    }

    void print(const string& label) {
        cout << label;
        for (int i = 0; i < size; i++) {
            cout << " " << data[i];
        }
        cout << "\n";
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    Array a1(n);
    a1.read();

    Array a2(a1);

    int modifyValue;
    cin >> modifyValue;
    a1.setElement(0, modifyValue);

    a1.print("Original:");
    a2.print("Clone:");

    return 0;
}
